            <div class="preview-group" aria-label="球体预览">
              <div class="preview-item">
                <span>当前</span>
                <div class="mini-ball" id="current-preview"></div>
              </div>
              <div class="preview-arrow" aria-hidden="true">→</div>
              <div class="preview-item">
                <span>下一个</span>
                <div class="mini-ball" id="next-preview"></div>
              </div>
            </div>

